.aventura-sim-container {
    padding: 28px;
    background: linear-gradient(170deg, #1b3a2d 0%, #0f2318 40%, #162e23 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #d4e8dc;
}
.aventura-sim-header {
    background: linear-gradient(135deg, rgba(45,106,79,0.4) 0%, rgba(27,67,50,0.6) 100%);
    border: 1px solid rgba(82,183,136,0.25);
    border-radius: 20px;
    padding: 36px 32px 28px;
    text-align: center;
    margin-bottom: 28px;
    position: relative;
    overflow: hidden;
}
.aventura-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, #52b788, #95d5b2, #2d6a4f);
}
.aventura-sim-header-badge {
    display: inline-block;
    background: rgba(82,183,136,0.15);
    border: 1px solid rgba(82,183,136,0.3);
    border-radius: 20px;
    padding: 4px 16px;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #95d5b2;
    margin-bottom: 14px;
}
.aventura-sim-header h1 {
    color: #b7e4c7;
    font-size: 1.6rem;
    font-weight: 700;
    margin: 0 0 8px 0;
}
.aventura-sim-subtitle {
    color: #74c69d;
    font-size: 0.9rem;
    margin: 0;
    opacity: 0.85;
}
.aventura-sim-period-counter {
    text-align: center;
    font-size: 1rem;
    color: #95d5b2;
    margin-bottom: 24px;
    padding: 10px;
    background: rgba(82,183,136,0.08);
    border-radius: 12px;
    border: 1px solid rgba(82,183,136,0.12);
}
.aventura-sim-period-counter span {
    margin: 0 4px;
}
.aventura-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 16px;
    margin-bottom: 28px;
}
.aventura-sim-kpi-card {
    background: rgba(21,43,33,0.7);
    border: 1px solid rgba(82,183,136,0.15);
    border-radius: 16px;
    padding: 20px 16px;
    text-align: center;
    transition: transform 0.2s ease, border-color 0.2s ease;
    position: relative;
}
.aventura-sim-kpi-card:hover {
    transform: translateY(-3px);
    border-color: rgba(82,183,136,0.35);
}
.aventura-sim-kpi-icon {
    font-size: 1.5rem;
    margin-bottom: 6px;
}
.aventura-sim-kpi-label {
    color: #74c69d;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
}
.aventura-sim-kpi-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #b7e4c7;
}
.aventura-sim-kpi-cash .aventura-sim-kpi-value { color: #52b788; }
.aventura-sim-kpi-revenue .aventura-sim-kpi-value { color: #40916c; }
.aventura-sim-kpi-ebitda .aventura-sim-kpi-value { color: #74c69d; }
.aventura-sim-kpi-guides .aventura-sim-kpi-value { color: #d8f3dc; }
.aventura-sim-kpi-env .aventura-sim-kpi-value { color: #2d6a4f; }
.aventura-sim-kpi-rep .aventura-sim-kpi-value { color: #ffd166; }
.aventura-sim-briefing {
    background: rgba(21,43,33,0.6);
    border: 1px solid rgba(82,183,136,0.2);
    border-left: 4px solid #52b788;
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 28px;
}
.aventura-sim-briefing-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 14px;
}
.aventura-sim-briefing-header h3 {
    color: #95d5b2;
    font-size: 1.05rem;
    font-weight: 600;
    margin: 0;
}
.aventura-sim-round-badge {
    background: rgba(82,183,136,0.2);
    border: 1px solid rgba(82,183,136,0.3);
    border-radius: 8px;
    padding: 3px 12px;
    font-size: 0.72rem;
    color: #95d5b2;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}
.aventura-sim-briefing-body {
    color: #c1dece;
    font-size: 0.88rem;
    line-height: 1.65;
}
.aventura-sim-controls {
    background: rgba(21,43,33,0.6);
    border: 1px solid rgba(82,183,136,0.2);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 28px;
}
.aventura-sim-controls h3 {
    color: #95d5b2;
    font-size: 1.05rem;
    font-weight: 600;
    margin: 0 0 20px 0;
}
.aventura-sim-input-group {
    margin-bottom: 18px;
}
.aventura-sim-input-group label {
    display: block;
    color: #95d5b2;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 6px;
    font-weight: 500;
}
.aventura-sim-controls select,
.aventura-sim-controls input[type="number"] {
    background: #0f2318;
    border: 1px solid rgba(82,183,136,0.25);
    color: #d4e8dc;
    border-radius: 10px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.92rem;
    transition: border-color 0.2s ease;
    font-family: inherit;
}
.aventura-sim-controls select:focus,
.aventura-sim-controls input[type="number"]:focus {
    border-color: #52b788;
    outline: none;
    box-shadow: 0 0 0 3px rgba(82,183,136,0.15);
}
.aventura-sim-controls select option {
    background: #152b21;
    color: #d4e8dc;
}
.aventura-sim-hint {
    display: block;
    color: #5a9e7c;
    font-size: 0.72rem;
    margin-top: 4px;
}
.aventura-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 22px;
}
.aventura-sim-submit-btn {
    background: linear-gradient(135deg, #2d6a4f, #40916c);
    border: none;
    color: #d8f3dc;
    font-weight: 600;
    padding: 12px 32px;
    border-radius: 12px;
    font-size: 0.95rem;
    transition: transform 0.15s ease, box-shadow 0.15s ease;
    cursor: pointer;
}
.aventura-sim-submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(45,106,79,0.4);
    background: linear-gradient(135deg, #40916c, #52b788);
    color: #ffffff;
}
.aventura-sim-undo-btn {
    border-color: rgba(82,183,136,0.3);
    color: #74c69d;
    border-radius: 10px;
    padding: 8px 18px;
    font-size: 0.82rem;
    background: transparent;
}
.aventura-sim-undo-btn:hover {
    background: rgba(82,183,136,0.1);
    color: #95d5b2;
}
.aventura-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 28px;
}
.aventura-sim-chart-wrapper {
    background: rgba(21,43,33,0.6);
    border: 1px solid rgba(82,183,136,0.15);
    border-radius: 16px;
    padding: 20px;
    min-height: 280px;
}
.aventura-sim-history {
    background: rgba(21,43,33,0.5);
    border: 1px solid rgba(82,183,136,0.15);
    border-radius: 16px;
    padding: 20px;
    overflow-x: auto;
}
.aventura-sim-container .table {
    color: #c1dece;
    margin: 0;
}
.aventura-sim-container .table thead th {
    border-color: rgba(82,183,136,0.2);
    color: #95d5b2;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    font-weight: 600;
    padding: 10px 12px;
}
.aventura-sim-container .table tbody td {
    border-color: rgba(82,183,136,0.1);
    padding: 10px 12px;
    font-size: 0.85rem;
}
.aventura-sim-container .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(82,183,136,0.04);
}
.aventura-sim-decision-panel {
    animation: aventuraFadeIn 0.3s ease;
}
@keyframes aventuraFadeIn {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
}
@media (max-width: 768px) {
    .aventura-sim-container { padding: 16px; }
    .aventura-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); gap: 10px; }
    .aventura-sim-kpi-value { font-size: 1.2rem; }
    .aventura-sim-header h1 { font-size: 1.2rem; }
    .aventura-sim-charts { grid-template-columns: 1fr; }
    .aventura-sim-chart-wrapper { min-height: 220px; }
    .aventura-sim-btn-row { flex-direction: column; }
    .aventura-sim-submit-btn { width: 100%; }
}
/* v1.1.0 end-of-game debrief panel */
.aventura-sim-results{background:rgba(82,183,136,0.08);border:1px solid rgba(82,183,136,0.55);border-left:4px solid #52b788;border-radius:12px;padding:16px 20px;margin:16px 0;}
.aventura-sim-results h3{margin:0 0 12px;color:#95d5b2;}
.aventura-results-grid{display:flex;flex-wrap:wrap;gap:12px;margin-bottom:10px;}
.aventura-result-metric{flex:1 1 130px;background:rgba(0,0,0,0.25);border-radius:8px;padding:10px 12px;display:flex;flex-direction:column;}
.aventura-result-metric .ar-label{font-size:12px;color:#74c69d;text-transform:uppercase;letter-spacing:.03em;}
.aventura-result-metric .ar-value{font-size:19px;font-weight:700;color:#fff;}
.aventura-insights-title{margin:10px 0 4px;color:#d8f3dc;}
.aventura-insights{margin:0;padding-left:18px;}
.aventura-insights li{margin-bottom:6px;line-height:1.4;color:#b7e4c7;}

