(function() {
    'use strict';

    class AventuraAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Turismo de Aventura en Colombia';
            this.version = '1.1.0';
            this.ROUNDS = [
                {
                    titleKey: 'round1_title',
                    titleFallback: 'Ronda 1 — Evaluación de Crisis',
                    descKey: 'round1_desc',
                    descFallback: '<b>Abril 2026 — Cuatro crisis simultáneas golpean a Expediciones Montaña Colombia.</b><br><br><b>Crisis 1:</b> El Ministerio de Ambiente restringe acceso al Parque La Calera (60% de ingresos). Los grupos se reducen de 2/día a 1/día y de 12 a 6 personas. Pérdida estimada: COP 3,456M anuales.<br><br><b>Crisis 2:</b> Nuevos requisitos ambientales exigen certificación de guías, equipo ultraligero y sistema de huella de carbono. Costo: COP 124M.<br><br><b>Crisis 3:</b> Viator y operadores extranjeros como Adventure Brasil erosionan la marca local. Reservas directas caen de 40% a 20%.<br><br><b>Crisis 4:</b> Un competidor (Aventuras Sierra) contamina Parque Gorgona. El Ministerio anuncia auditoría a todos los operadores en 60 días.<br><br>Seleccione una estrategia y nivel de inversión para este trimestre.',
                    panel: 1
                },
                {
                    titleKey: 'round2_title',
                    titleFallback: 'Ronda 2 — Negociación con el Ministerio',
                    descKey: 'round2_desc',
                    descFallback: '<b>Negociación directa con el Ministerio de Ambiente sobre las restricciones en La Calera.</b><br><br>Expediciones Montaña tiene 16 años sin incidentes ambientales. Puede argumentar: (1) track record impecable, (2) estándares superiores al promedio, (3) impacto económico en comunidades locales (32 empleos, posadas comunitarias), (4) propuesta de alianza científica para monitoreo ambiental.<br><br>Un enfoque <b>colaborativo</b> con oferta de ecotasa tiene mayor probabilidad de éxito. Un enfoque <b>agresivo</b> puede obtener más concesiones pero arriesga la relación. Un enfoque <b>concesivo</b> garantiza resultado modesto.<br><br>El resultado ideal: 1.5 grupos/día (vs. 1 actual), reduciendo la brecha de ingresos a COP 1,728M.',
                    panel: 2
                },
                {
                    titleKey: 'round3_title',
                    titleFallback: 'Ronda 3 — Auditoría Ambiental Sorpresa',
                    descKey: 'round3_desc',
                    descFallback: '<b>El equipo auditor del Ministerio llega con tres hallazgos:</b><br><br><b>Hallazgo Menor:</b> Registros de residuos incompletos. Solución: 2 semanas de documentación. Sin penalidad directa.<br><br><b>Hallazgo Moderado:</b> Un guía sin certificación de Primeros Auxilios Ambiental. Multa potencial: COP 5M. Plazo: 30 días para corrección.<br><br><b>Hallazgo Mayor:</b> En octubre 2025, un grupo acampó fuera de zona permitida. Expediciones lo reportó verbalmente, pero no hay evidencia escrita. Si el Ministerio lo interpreta como ocultamiento, puede revocar la concesión.<br><br>Elija su estrategia de respuesta y asigne presupuesto para remediación.',
                    panel: 3
                },
                {
                    titleKey: 'round4_title',
                    titleFallback: 'Ronda 4 — Plan Estratégico de Sostenibilidad',
                    descKey: 'round4_desc',
                    descFallback: '<b>Presentación al Board: Plan de supervivencia y crecimiento post-crisis.</b><br><br>Debe definir:<br>• <b>Supervivencia 2026–2027:</b> Cómo alcanzar EBITDA positivo en 18 meses<br>• <b>Crecimiento 2027–2029:</b> Escalar operación, mejorar marca vs. Viator/Adventure Brasil, inversión digital<br>• <b>Sostenibilidad:</b> Posicionar a Expediciones como operador de excelencia ambiental — diferenciador competitivo ante turistas globales que pagan premium por experiencias sustentables<br><br>El nivel de <b>excelencia ambiental</b> cuesta más pero abre mercado premium. La <b>alianza para escalar</b> reduce riesgo pero comparte utilidad.',
                    panel: 4
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 2000,
                    quarterlyRevenue: 864,
                    quarterlyCosts: 1300,
                    ebitda: -436,
                    guides: 24,
                    certifiedGuides: 8,
                    envScore: 70,
                    reputation: 75,
                    laCaleraCap: 0.4,
                    compliancePaid: 0,
                    negotiationResult: 0,
                    auditPenalty: 0,
                    cashHistory: [],
                    ebitdaHistory: [],
                    envHistory: [],
                    repHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategy: 'expansion',
                    investment: 150,
                    negotiation: 'collaborative',
                    ecoTax: 25,
                    auditResponse: 'full_acceptance',
                    remediation: 20,
                    growthStrategy: 'organic',
                    sustainLevel: 'standard'
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var period = window.mySimulation.state.currentPeriod || 1;

            if (period === 1) {
                var stratEl = document.getElementById('strategySelect');
                if (stratEl) decisions.strategy = stratEl.value;
                var invEl = document.getElementById('investmentInput');
                if (invEl) decisions.investment = parseFloat(invEl.value) || 0;
                if (decisions.investment < 0 || decisions.investment > 500) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('investment_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 2) {
                var negEl = document.getElementById('negotiationSelect');
                if (negEl) decisions.negotiation = negEl.value;
                var taxEl = document.getElementById('ecoTaxInput');
                if (taxEl) decisions.ecoTax = parseFloat(taxEl.value) || 0;
                if (decisions.ecoTax < 0 || decisions.ecoTax > 100) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('ecotax_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 3) {
                var audEl = document.getElementById('auditSelect');
                if (audEl) decisions.auditResponse = audEl.value;
                var remEl = document.getElementById('remediationInput');
                if (remEl) decisions.remediation = parseFloat(remEl.value) || 0;
                if (decisions.remediation < 0 || decisions.remediation > 60) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('remediation_warning'), 'warning'
                    );
                    return false;
                }
            } else if (period === 4) {
                var grEl = document.getElementById('growthSelect');
                if (grEl) decisions.growthStrategy = grEl.value;
                var susEl = document.getElementById('sustainSelect');
                if (susEl) decisions.sustainLevel = susEl.value;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var revenue = ds.quarterlyRevenue;
            var costs = ds.quarterlyCosts;
            var envDelta = 0;
            var repDelta = 0;
            var guidesLost = 0;
            var narrative = '';

            if (period === 1) {
                var inv = Math.min(d.investment, ds.cash * 0.5);
                if (d.strategy === 'cost_reduction') {
                    guidesLost = Math.round(inv / 35);
                    costs = costs - (guidesLost * 45) - (inv * 0.4);
                    revenue = revenue * 0.95;
                    repDelta = -5;
                    envDelta = 2;
                    narrative = window.mySimulation.t('r1_cost') || 'Se redujo estructura de costos. Se perdieron guías experimentados.';
                } else if (d.strategy === 'expansion') {
                    revenue = revenue + (inv * 1.2);
                    costs = costs + (inv * 0.6);
                    envDelta = 5;
                    repDelta = 3;
                    narrative = window.mySimulation.t('r1_expansion') || 'Se abrieron rutas en nuevos parques nacionales.';
                } else if (d.strategy === 'urban_pivot') {
                    revenue = revenue + (inv * 0.8);
                    costs = costs + (inv * 0.5);
                    envDelta = -2;
                    repDelta = -3;
                    narrative = window.mySimulation.t('r1_urban') || 'Se lanzaron experiencias de aventura urbana en Medellín y Bogotá.';
                } else if (d.strategy === 'partnership') {
                    revenue = revenue + 250;
                    costs = costs + 80;
                    repDelta = -8;
                    envDelta = 3;
                    narrative = window.mySimulation.t('r1_partner') || 'Se negoció alianza con operador internacional. Se pierde independencia parcial.';
                }
                costs = costs + 31;
                ds.compliancePaid = 124;
                ds.cash = ds.cash - inv;
            } else if (period === 2) {
                var capGain = 0;
                var taxCost = d.ecoTax / 4;
                if (d.negotiation === 'collaborative') {
                    capGain = 0.225;
                    envDelta = 8 + Math.min(d.ecoTax / 10, 5);
                    repDelta = 6;
                    narrative = window.mySimulation.t('r2_collab') || 'Negociación colaborativa exitosa. Se obtuvieron 1.5 grupos/día en La Calera.';
                } else if (d.negotiation === 'aggressive') {
                    capGain = 0.3;
                    envDelta = 2;
                    repDelta = -4;
                    narrative = window.mySimulation.t('r2_aggr') || 'Se presionó al Ministerio. Se obtuvieron 2 grupos/día pero la relación quedó tensa.';
                } else {
                    capGain = 0.15;
                    envDelta = 5 + Math.min(d.ecoTax / 8, 4);
                    repDelta = 2;
                    narrative = window.mySimulation.t('r2_conc') || 'Enfoque concesivo. Mejora modesta en acceso, buena relación con Ministerio.';
                }
                ds.laCaleraCap = Math.min(ds.laCaleraCap + capGain, 1.0);
                var laCalRevenueGain = capGain * 1728;
                revenue = revenue + laCalRevenueGain;
                costs = costs + taxCost;
                ds.negotiationResult = capGain;
            } else if (period === 3) {
                var fine = 0;
                var remCost = d.remediation;
                if (d.auditResponse === 'full_acceptance') {
                    fine = 8;
                    envDelta = 12 + Math.round(d.remediation / 5);
                    repDelta = 8;
                    narrative = window.mySimulation.t('r3_accept') || 'Aceptación responsable. Ministerio valora transparencia. Concesión asegurada.';
                } else if (d.auditResponse === 'partial_contest') {
                    fine = 5;
                    envDelta = 5 + Math.round(d.remediation / 8);
                    repDelta = -3;
                    narrative = window.mySimulation.t('r3_partial') || 'Se contestó hallazgo mayor. Resultado mixto: multa reducida, relación deteriorada.';
                } else {
                    fine = 2;
                    envDelta = -8;
                    repDelta = -12;
                    narrative = window.mySimulation.t('r3_contest') || 'Se contestaron todos los hallazgos. Ministerio considera falta de cooperación. Riesgo elevado.';
                }
                costs = costs + fine + remCost;
                ds.auditPenalty = fine;
            } else if (period === 4) {
                var growthMult = 1.0;
                var costMult = 1.0;
                if (d.growthStrategy === 'organic') {
                    growthMult = 1.15;
                    costMult = 1.05;
                    repDelta = 5;
                } else if (d.growthStrategy === 'aggressive_growth') {
                    growthMult = 1.35;
                    costMult = 1.2;
                    repDelta = -2;
                } else {
                    growthMult = 1.25;
                    costMult = 1.08;
                    repDelta = 3;
                }
                revenue = revenue * growthMult;
                costs = costs * costMult;

                if (d.sustainLevel === 'minimum') {
                    envDelta = 3;
                    costs = costs + 10;
                } else if (d.sustainLevel === 'standard') {
                    envDelta = 12;
                    costs = costs + 40;
                    repDelta = repDelta + 8;
                } else {
                    envDelta = 25;
                    costs = costs + 80;
                    repDelta = repDelta + 15;
                    revenue = revenue * 1.1;
                }
                narrative = window.mySimulation.t('r4_result') || 'Plan estratégico presentado al Board.';
            }

            revenue = Math.round(revenue);
            costs = Math.round(costs);
            var ebitda = revenue - costs;
            ds.quarterlyRevenue = revenue;
            ds.quarterlyCosts = costs;
            ds.ebitda = ebitda;
            ds.cash = Math.round(ds.cash + ebitda);
            ds.guides = Math.max(6, ds.guides - guidesLost);
            ds.envScore = Math.max(0, Math.min(100, ds.envScore + envDelta));
            ds.reputation = Math.max(0, Math.min(100, ds.reputation + repDelta));

            ds.cashHistory.push(ds.cash);
            ds.ebitdaHistory.push(ebitda);
            ds.envHistory.push(ds.envScore);
            ds.repHistory.push(ds.reputation);

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            if (state.currentPeriod >= (state.maxPeriods || this.ROUNDS.length)) { var selfC = this; setTimeout(function() { try { selfC._renderCompletion(state); } catch (e) {} }, 0); }

            return {
                period: period,
                revenue: revenue,
                costs: costs,
                ebitda: ebitda,
                cash: ds.cash,
                guides: ds.guides,
                envScore: ds.envScore,
                reputation: ds.reputation,
                narrative: narrative
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
