        getPerformanceSummary(history) {
            if (!history.length) return {};
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function') ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var lastRecord = history[history.length - 1];
            var r = lastRecord.results || {};
            var totalEbitda = history.reduce(function(s, h) { return s + (h.results ? h.results.ebitda : 0); }, 0);
            var finalCash = r.cash || 0;
            var finalEnv = r.envScore || 0;
            var finalRep = r.reputation || 0;
            var compositeScore = Math.round((finalCash > 0 ? 25 : 0) + (finalEnv * 0.4) + (finalRep * 0.35));

            var performance = T('perf_beginner');
            if (compositeScore >= 40 && totalEbitda > -500) performance = T('perf_competent');
            if (compositeScore >= 60 && totalEbitda > 0) performance = T('perf_good');
            if (compositeScore >= 75 && finalEnv >= 80) performance = T('perf_excellent');
            if (compositeScore >= 85 && finalEnv >= 90 && finalRep >= 85) performance = T('perf_exceptional');

            var insights = [];
            if (finalEnv >= 85) insights.push(T('insight_env_excellent'));
            if (finalEnv < 60) insights.push(T('insight_env_low'));
            if (finalRep >= 80) insights.push(T('insight_rep_good'));
            if (finalRep < 50) insights.push(T('insight_rep_low'));
            if (totalEbitda > 200) insights.push(T('insight_fin_strong'));
            if (totalEbitda < -800) insights.push(T('insight_fin_weak'));
            if (finalCash < 500) insights.push(T('insight_cash_low'));

            return {
                compositeScore: compositeScore,
                totalEbitda: totalEbitda,
                finalCash: finalCash,
                finalEnvScore: finalEnv,
                finalReputation: finalRep,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            var period = results.period;
            if (period === 1 && results.ebitda < -400) return window.mySimulation.t('hint_deep_loss');
            if (period === 1 && results.guides < 15) return window.mySimulation.t('hint_few_guides');
            if (period === 2 && state.domainState.laCaleraCap < 0.5) return window.mySimulation.t('hint_low_access');
            if (period === 3 && results.envScore < 60) return window.mySimulation.t('hint_env_risk');
            if (period === 3 && results.reputation < 55) return window.mySimulation.t('hint_rep_risk');
            if (period === 4 && results.ebitda > 0) return window.mySimulation.t('hint_recovery');
            if (results.cash < 500) return window.mySimulation.t('hint_cash_low');
            return null;
        }

